<?php
require_auth(['admin']);
$pageTitle = 'Đội ngũ đại sứ';
$students = rows("SELECT u.*, COUNT(DISTINCT c.id) AS chats, COALESCE(SUM(al.leads),0) AS leads FROM users u LEFT JOIN conversations c ON c.ambassador_id = u.id LEFT JOIN affiliate_links al ON al.user_id = u.id WHERE u.role IN ('student','ambassador') GROUP BY u.id ORDER BY u.role = 'ambassador' DESC, u.name");
?>
<div class="page-actions"><p class="page-intro">Quản lý hồ sơ, quyền trực inbox và trạng thái hoạt động.</p><div class="summary-pills"><span><i class="online"></i> <?= (int) scalar("SELECT COUNT(*) FROM users WHERE role='ambassador' AND is_online=1") ?> đang online</span><span><?= (int) scalar("SELECT COUNT(*) FROM users WHERE role='ambassador'") ?> đại sứ</span></div></div>
<section class="panel-card"><div class="panel-head"><div></div><a href="index.php?page=admin-rewards">Quản lý phân hạng <i class="bi bi-arrow-right"></i></a></div><div class="table-responsive"><table class="table clean-table align-middle"><thead><tr><th>Thành viên</th><th>Ngành học</th><th>Vai trò</th><th>Phân hạng</th><th>Hiệu quả</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($students as $student): ?><tr><td><div class="person-cell"><span class="avatar avatar-sm"><?= e(initials($student['name'])) ?></span><div><strong><?= e($student['name']) ?> <?php if ($student['role'] === 'ambassador'): ?><i class="bi bi-patch-check-fill text-primary"></i><?php endif; ?></strong><small><?= e($student['student_code']) ?> | <?= e($student['hometown']) ?></small></div></div></td><td><?= e($student['major']) ?><small class="d-block text-muted">Năm <?= (int) $student['study_year'] ?></small></td><td><span class="badge text-bg-<?= $student['role'] === 'ambassador' ? 'primary' : 'secondary' ?>-subtle"><?= e(role_label($student['role'])) ?></span></td><td><span class="tier-badge tier-<?= e($student['ambassador_tier']) ?>"><?= e(ucfirst($student['ambassador_tier'])) ?></span></td><td><span class="me-3"><strong><?= (int) $student['chats'] ?></strong> chats</span><span><strong><?= (int) $student['leads'] ?></strong> leads</span></td><td><span class="presence <?= $student['is_online'] ? 'online' : '' ?>"></span> <?= $student['status'] === 'active' ? 'Hoạt động' : 'Tạm khóa' ?></td><td><form method="post" action="actions.php?action=update_ambassador" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) $student['id'] ?>"><input type="hidden" name="status" value="<?= $student['status'] ?>"><select class="form-select form-select-sm" name="role" aria-label="Vai trò"><option value="student" <?= $student['role'] === 'student' ? 'selected' : '' ?>>Sinh viên</option><option value="ambassador" <?= $student['role'] === 'ambassador' ? 'selected' : '' ?>>Đại sứ</option></select><button class="btn btn-sm btn-light border">Lưu</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
